from typing import Protocol, runtime_checkable

@runtime_checkable
class Speaker(Protocol):
    def speak(self) -> str: ...

class Dog:
    def speak(self) -> str:
        return "Woof"

class Cat:
    def speak(self) -> str:
        return "Meow"

class Rock:
    pass

def announce_all(items):
    return [item.speak() for item in items if isinstance(item, Speaker)]

print(announce_all([Dog(), Rock(), Cat()]))
